function renderSlots(template, values) {
  if (
    typeof template !== "string" ||
    values === null ||
    typeof values !== "object" ||
    Array.isArray(values)
  ) {
    return null;
  }

  for (const key of Object.keys(values)) {
    if (typeof values[key] !== "string") return null;
  }

  const pattern = /\{\{([A-Za-z][A-Za-z0-9_]*)\}\}/g;
  let result = "";
  let lastIndex = 0;
  let match;

  while ((match = pattern.exec(template)) !== null) {
    const start = match.index;
    const escaped = start > 0 && template[start - 1] === "\\";
    const textEnd = escaped ? start - 1 : start;

    result += template.slice(lastIndex, textEnd);

    if (
      !escaped &&
      Object.prototype.hasOwnProperty.call(values, match[1])
    ) {
      result += values[match[1]];
    } else {
      result += match[0];
    }

    lastIndex = pattern.lastIndex;
  }

  return result + template.slice(lastIndex);
}
